-- 0000_baseline.sql
--
-- FROZEN BASELINE. This reproduces the schema that the sqlx history already
-- applied to Supabase Postgres, moved here unchanged in meaning (ADR-0011):
--
--   api/migrations/20260811000000_initial_properties.sql
--   api/migrations/20261125000000_properties_owner_id.sql
--
-- Do not edit this file. A change to the schema is a new migration generated by
-- `pnpm --filter web db:generate`, reviewed as SQL, with the hand-authored
-- statements below kept intact. drizzle-kit cannot model RLS, grants, or the
-- backfill, and `drizzle-kit push` would drop them; see scripts/migrate.ts.
--
-- Every statement is idempotent so this file converges against a database that
-- already carries the objects. The journal marks it applied on such a database
-- (see scripts/migrate.ts), so normally only a fresh database executes it.

create extension if not exists pgcrypto;
--> statement-breakpoint
create table if not exists properties (
    id uuid primary key default gen_random_uuid(),
    name text not null check (length(btrim(name)) > 0),
    address text not null check (length(btrim(address)) > 0),
    type text not null check (type in ('residential', 'commercial', 'lot')),
    units integer check (units is null or units >= 0),
    is_active boolean not null default true,
    created_at timestamptz not null default now()
);
--> statement-breakpoint
create index if not exists properties_active_created_at_idx
    on properties (is_active desc, created_at desc);
--> statement-breakpoint

-- Every property belongs to one landlord account (ADR-0008). The column is
-- added nullable and constrained after the backfill, exactly as the applied
-- migration did, so the history stays faithful.
alter table properties
    add column if not exists owner_id uuid references auth.users (id) on delete cascade;
--> statement-breakpoint
create index if not exists properties_owner_id_idx on properties (owner_id);
--> statement-breakpoint

-- Historical backfill. Inert on a database with no unowned rows (production
-- started empty), and it aborts rather than guessing an owner when rows exist
-- without the seeded Bootstrap user. Kept so a fresh environment cannot skip
-- the guard.
do $$
declare
    bootstrap_owner_email constant text := 'owner@m-proper.test';
    bootstrap_owner_id uuid;
    unowned_rows bigint;
begin
    select count(*) into unowned_rows from properties where owner_id is null;

    if unowned_rows = 0 then
        return;
    end if;

    select id into bootstrap_owner_id
    from auth.users
    where lower(email) = lower(bootstrap_owner_email);

    if bootstrap_owner_id is null then
        raise exception using
            message = format(
                'properties.owner_id backfill aborted: %s row(s) have no owner but the bootstrap owner %s is absent from auth.users. Seed it, then rerun this migration. No owner was guessed.',
                unowned_rows,
                bootstrap_owner_email
            ),
            hint = 'The migration never assigns rows to another account; it aborts instead.';
    end if;

    update properties set owner_id = bootstrap_owner_id where owner_id is null;
end
$$;
--> statement-breakpoint
alter table properties alter column owner_id set not null;
--> statement-breakpoint

-- Defence in depth. The app connects as the table owner, which bypasses RLS
-- unless FORCE ROW LEVEL SECURITY is set (it is not), so app-level scoping
-- remains the primary control. These policies matter if the Data API path is
-- ever re-enabled.
alter table properties enable row level security;
--> statement-breakpoint
drop policy if exists properties_select_own on properties;
--> statement-breakpoint
create policy properties_select_own on properties
    for select to authenticated
    using (owner_id = auth.uid());
--> statement-breakpoint
drop policy if exists properties_insert_own on properties;
--> statement-breakpoint
create policy properties_insert_own on properties
    for insert to authenticated
    with check (owner_id = auth.uid());
--> statement-breakpoint
drop policy if exists properties_delete_own on properties;
--> statement-breakpoint
create policy properties_delete_own on properties
    for delete to authenticated
    using (owner_id = auth.uid());
--> statement-breakpoint

-- No update policy: the product exposes no update route. It lands with that
-- route and adopts the same predicate.

-- Close the direct Data API path: `anon` and `authenticated` lose every
-- privilege, even if the API is re-enabled. The app's own role owns the table
-- and is unaffected.
revoke all on table properties from anon, authenticated;
